def transform(grid):
    g=[row[:] for row in grid]
    shifts={1:(-1,2),2:(0,-4),3:(3,0),6:(-6,0)}
    h,w=len(g),len(g[0])
    for color,(dr,dc) in shifts.items():
        pts=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==color]
        for r,c in pts:
            rr,cc=r+dr,c+dc
            if not (0<=rr<h and 0<=cc<w): continue
            g[rr][cc]=color
            # connect with 5, first horizontal then vertical for color 1's elbow
            cr,ccur=r,c
            while ccur!=cc:
                ccur += 1 if cc>ccur else -1
                if (cr,ccur)!=(rr,cc) and g[cr][ccur]==0: g[cr][ccur]=5
            while cr!=rr:
                cr += 1 if rr>cr else -1
                if (cr,cc)!=(rr,cc) and g[cr][cc]==0: g[cr][cc]=5
    return g
